    // now we have rows: [][]u8 where rows[i][j] is cell.
    // check O connection top-bottom
    if (hasConnection(allocator, rows, 'O', .top_bottom)) return 'O';
    if (hasConnection(allocator, rows, 'X', .left_right)) return 'X';
