fn hasConnection(allocator: mem.Allocator, board: [][]const u8, player: u8, kind: ConnectionKind) !bool {
    // kind: 0 for top-bottom (O), 1 for left-right (X)
    const rows = board.len;
    const width = board[0].len;
    // allocate visited
    var visited = try allocator.alloc([]bool, rows);
    defer allocator.free(visited);
    for (visited) |vis_row, i| {
        vis_row.* = try allocator.alloc(bool, width);
        defer allocator.free(vis_row.*);
        // initialize false
        std.mem.setBytes(vis_row.*, 0);
    }
    // queue: we can use array list
    var queue = std.ArrayList(usize).init(allocator);
    defer queue.deinit();
    // push all start cells
    switch (kind) {
        .top_bottom => {
            // start from top row (row 0) cells that are player
            for (board[0]) |cell, j| {
                if (cell == player) {
                    // encode position as i*width + j
                    try queue.append(0 * width + j);
                    visited[0][j] = true;
                }
            }
        }
        .left_right => {
            // start from left column (col 0) cells that are player
            for (board) |row, i| {
                if (row[0] == player) {
                    try queue.append(i * width + 0);
                    visited[i][0] = true;
                }
            }
        }
    }
    while (queue.items.len > 0) {
        const pos = queue.pop() orelse unreachable;
        const r = pos / width;
        const c = pos % width;
        // if reached target edge
        switch (kind) {
            .top_bottom => {
                if (r == rows - 1) {
                    return true;
                }
            }
            .left_right => {
                if (c == width - 1) {
                    return true;
